<script setup lang="ts">
import { reactive, ref, watch } from 'vue'; import { Database, FolderOpen, HardDrive, Save, Server } from 'lucide-vue-next'; import { api } from '../lib/api'; import { notify, state } from '../stores/app'; import type { Settings } from '../types'
const form=reactive<Settings>({concurrency:3,maxFileSizeMb:500,outputDirectory:'./outputs',defaultMode:'crop',defaultFormat:'png',defaultQuality:90,autoRetryCount:1,requestTimeoutMinutes:30,maxResourcePercent:70,theme:'system'}); watch(()=>state.settings,s=>{if(s)Object.assign(form,s)},{immediate:true})
async function save(){try{state.settings=await api.saveSettings(form);notify('设置已保存')}catch(e){notify(e instanceof Error?e.message:'保存失败')}}
const choosingDirectory=ref(false)
async function selectDirectory(){if(choosingDirectory.value)return;choosingDirectory.value=true;try{const {outputDirectory}=await api.selectOutputDirectory();form.outputDirectory=outputDirectory;notify('目录已填入，请点击“保存设置”生效')}catch(e){notify(e instanceof Error?e.message:'选择目录失败')}finally{choosingDirectory.value=false}}
</script>
<template><section class="page settings"><header class="page-head"><div><h1>设置</h1><p>管理默认处理策略、性能上限与界面外观。</p></div><button class="primary" @click="save"><Save :size="18"/>保存设置</button></header><div class="settings-grid"><article class="panel setting-section"><h2>处理设置</h2><label>默认处理模式<select v-model="form.defaultMode"><option value="crop">局部修复（原尺寸）</option><option value="blur">模糊覆盖</option><option value="solid">纯色覆盖</option><option value="smart">AI 智能修复</option></select></label><label>默认输出格式<select v-model="form.defaultFormat"><option value="png">PNG</option><option value="jpg">JPG</option></select></label><label>默认输出质量<select v-model.number="form.defaultQuality"><option :value="80">80%</option><option :value="90">90%</option><option :value="100">100%</option></select></label><label>默认保存目录<div class="directory-field"><input v-model="form.outputDirectory"/><button type="button" class="secondary" :disabled="choosingDirectory" @click="selectDirectory"><FolderOpen :size="17"/>{{choosingDirectory?'正在打开…':'选择目录'}}</button></div></label></article><article class="panel setting-section"><h2>性能设置</h2><label>最大并发任务<select v-model.number="form.concurrency"><option v-for="n in [1,2,3,5,10]" :key="n" :value="n">{{n}}</option></select></label><label>单个文件最大大小（MB）<input v-model.number="form.maxFileSizeMb" type="number" min="10" max="2000"/></label><label>最大处理资源（%）<input v-model.number="form.maxResourcePercent" type="number" min="10" max="100"/></label><label>自动重试次数<select v-model.number="form.autoRetryCount"><option :value="0">0</option><option :value="1">1</option><option :value="2">2</option><option :value="3">3</option></select></label><label>请求超时（分钟）<select v-model.number="form.requestTimeoutMinutes"><option :value="10">10</option><option :value="30">30</option><option :value="60">60</option><option :value="120">120</option></select></label></article><article class="panel setting-section"><h2>外观</h2><div class="theme-pick"><button v-for="choice in ['light','dark','system']" :key="choice" :class="{selected:form.theme===choice}" @click="form.theme=choice as Settings['theme']">{{choice==='light'?'Light Mode':choice==='dark'?'Dark Mode':'System'}}</button></div></article><article class="panel system-card"><h2>系统</h2><p><Server :size="18"/>当前版本 <b>0.2.0</b></p><p><Database :size="18"/>数据库状态 <b class="ok">已连接</b></p><p><HardDrive :size="18"/>输出目录状态 <b class="ok">保存时校验</b></p><p><HardDrive :size="18"/>处理引擎 <b>Sharp + FFmpeg</b></p></article></div></section></template>
